package pe.edu.upeu.casaonada.pago.integration;
import pe.edu.upeu.casaonada.pago.domain.EstadoPago; import pe.edu.upeu.casaonada.pago.dto.PagoRequest; import java.util.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component @ConditionalOnProperty(name="app.mercadopago.enabled",havingValue="true") public class MercadoPagoGateway {
 private final RestClient client; public MercadoPagoGateway(@Value("${app.mercadopago.base-url:https://api.mercadopago.com}") String base,@Value("${app.mercadopago.access-token}") String token){this.client=RestClient.builder().baseUrl(base).defaultHeader("Authorization","Bearer "+token).build();}
 @SuppressWarnings("unchecked") public Resultado pagar(PagoRequest r,String key){ Map<String,Object> body=new LinkedHashMap<>(); body.put("transaction_amount",r.monto());body.put("description",r.descripcion());body.put("payment_method_id",r.paymentMethodId());body.put("installments",r.installments()==null?1:r.installments());body.put("payer",Map.of("email",r.payerEmail())); if(r.token()!=null&&!r.token().isBlank())body.put("token",r.token()); Map<String,Object> res=client.post().uri("/v1/payments").header("X-Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class); String id=Objects.toString(res.get("id"),null), status=Objects.toString(res.get("status"),"pending"); EstadoPago e=switch(status){case "approved"->EstadoPago.APROBADO;case "rejected"->EstadoPago.RECHAZADO;case "cancelled"->EstadoPago.CANCELADO;case "refunded"->EstadoPago.REEMBOLSADO;default->EstadoPago.PENDIENTE;}; return new Resultado(id,e); }
 public record Resultado(String providerPaymentId,EstadoPago estado){}
}
